import "core-js/modules/es6.function.name";
import { getList, getDetail as _getDetail, add, update, remove, getColumnList as _getColumnList } from "@/api/data/devicecolumnunit";
import ModeChwserverDialog from "@/views/h3c/components/modeChwserverDialog.vue";
export default {
  components: {
    ModeChwserverDialog: ModeChwserverDialog
  },
  props: ['keyId', 'name', 'h3cModelType', 'h3cModelId'],
  data: function data() {
    return {
      keyword: '',
      form: {
        modelId: '1777628814769086465',
        appId: '874721629439350',
        appType: 'c_hw_server'
      },
      columnForm: {
        modelId: '1777628814769086465',
        appId: '874721629439350',
        appType: 'c_hw_server'
      },
      id: '',
      columnList: [],
      tableHeight: '60vh',
      columnFormVisible: false,
      dataDialogVisible: false,
      devicecolumnunitList: [],
      availableList: [{
        dictKey: '0',
        dictValue: '可用'
      }, {
        dictKey: '2',
        dictValue: 'Ping不可达'
      }, {
        dictKey: '3',
        dictValue: '协议连接失败'
      }, {
        dictKey: '4',
        dictValue: '未知(显示:–)'
      }],
      healthList: [{
        dictKey: '0',
        dictValue: '正常'
      }, {
        dictKey: '1',
        dictValue: '未知(显示:–)'
      }, {
        dictKey: '2',
        dictValue: ''
      }, {
        dictKey: '3',
        dictValue: '通知'
      }, {
        dictKey: '4',
        dictValue: '警告'
      }, {
        dictKey: '5',
        dictValue: '次要'
      }, {
        dictKey: '6',
        dictValue: '重要'
      }, {
        dictKey: '7',
        dictValue: '紧急'
      }],
      catalogHeight: "calc(100% - 200px)" // 默认值高度：50px搜索框高度（21外边距）
    };
  },
  mounted: function mounted() {
    if (!this.name) {
      this.name = 'H3C 模型base';
    }
    if (this.keyId) {
      this.form.modelId = this.keyId;
      this.columnForm.modelId = this.keyId;
    }
    if (this.h3cModelType) {
      this.form.appType = this.h3cModelType;
      this.form.appId = this.h3cModelId;
      this.columnForm.appId = this.h3cModelId;
      this.columnForm.appType = this.h3cModelType;
    }
    //this.getDeatil(this.$route.query.id)
    //加载列表
    this.getDataList();
    // 设置表格高度
    this.setTableHeight();
    //加载 Column列表
    this.getColumnList();
  },
  methods: {
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight - 230 + 'px';
    },
    getDataList: function getDataList() {
      var _this = this;
      this.loading = true;
      getList(1, 300, {
        modelId: this.form.modelId
      }).then(function (res) {
        var data = res.data;
        _this.devicecolumnunitList = data.records;
        _this.loading = false;
      });
    },
    getDetail: function getDetail(id) {
      var _this2 = this;
      //获取详情
      _getDetail(id).then(function (res) {
        _this2.columnForm = res.data;
      });
    },
    getColumnList: function getColumnList() {
      //获取模板对应 字段
      var _this = this;
      _getColumnList(1, 300, {
        modelId: this.form.modelId
      }).then(function (res) {
        var data = res.data;
        _this.columnList = data.records;
      });
    },
    columnChange: function columnChange(code) {
      //选择字段
      var items = this.columnList.filter(function (item) {
        return item.id === "" + code;
      });
      if (items != null && items.length > 0) {
        this.columnForm.colId = items[0].id;
        this.columnForm.colName = items[0].code + ' / ' + items[0].name;
      }
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code != '') {
        var items = dictList.filter(function (item) {
          return item.dictKey === "" + code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    dataDialogShowHandler: function dataDialogShowHandler() {
      //数据预览
      this.dataDialogVisible = true;
    },
    addDialogShowHandler: function addDialogShowHandler() {
      //弹框
      this.columnFormVisible = true;
      this.columnForm = {};
      this.columnForm.modelId = this.form.modelId;
      this.columnForm.appId = this.form.appId;
      this.columnForm.appType = this.form.appType;
    },
    addHandler: function addHandler() {
      var _this3 = this;
      //新增
      this.$refs.columnForm.validate(function (valid) {
        if (valid) {
          if (_this3.columnForm.id) {
            //修改
            update(_this3.columnForm).then(function (res) {
              _this3.$message({
                type: "success",
                message: "操作成功!" + res.code
              });
              _this3.getDataList();
              _this3.columnFormVisible = false;
              _this3.columnForm = {};
            }).catch(function () {});
          } else {
            //新增
            add(_this3.columnForm).then(function (res) {
              _this3.$message({
                type: "success",
                message: "操作成功!" + res.code
              });
              _this3.getDataList();
              _this3.columnFormVisible = false;
              _this3.columnForm = {};
            }).catch(function () {});
          }
        }
      });
    },
    handleEdit: function handleEdit(row) {
      //编辑
      if (row) {
        this.columnFormVisible = true;
        this.columnForm = row || {};
      }
    },
    handleDel: function handleDel(row) {
      var _this4 = this;
      //删除
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定删除",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function () {
        return remove(row.id);
      }).then(function () {
        _this4.$message({
          type: "success",
          message: "操作成功!"
        });
        _this4.getDataList();
      });
    }
  }
};
